	STRING ASIS	BLANKS OFF	*******************************************************************                     The Print Manager *                  GraphiCard Driver  V2.0** May 1988*    This driver is originally developed by StyleWare, Inc. using *    the Printer Port Driver v1.0 as its basis.** v 1.0* June 16, 1988         Suki Lee*    Converted StyleWare's source from APW to MAX.*    * June 30, 1988         Suki Lee*    Changed macros _ReadBlock and _WriteBlock to their new names:*    _TextReadBlock and _TextWriteBlock. Eliminated need to use*    Special.Macros.** July 13, 1988         Suki Lee*    Bug fix:*       The routine IsItSafe checks the wrong bit for the card's*       signature. Slot 1 always qualifies because the bit being*       checked is for a device type of printer. The routine will*       now look for $14, the specific signature of the GraphiCard.** v2.0* October 10, 1988    Suki Lee*    Fixed DevStartUp to remove two pointers off the stack since the*    same call in the AppleTalk driver uses two pointers as input.** October 12, 1988    Eric Soldan*    Changed driver to be as general and non-assuming as*    possible.  There may be cards that can not be set such that*    they do not try to interpret $89's as a special control*    character.  If there is such a card, then part of the buffer*    will be sent, then the control character will be changed*    from an $89 to an $81, and then the process will be*    repeated until an $81 is encountered.  This process is*    repeated until the buffer is entirely sent.  After the*    buffer is sent, then the special character is set back to*    an $89.** The "recommended way" to ID pascal and BASIC devices is:** Pascal I.D bytes           CN05=38  CN07=18  CN0B=01  CN0C=ci* Apple parallel intf card:  CN05=48  CN07=48** December 16, 1988   Suki Lee*    Added new header to denote this as a driver which will support *    new calls. This header is 2 words long: first word is 0 *    followed by a call count word.** January 18, 1989     Suki Lee*    Removed DevInitBack since none of the code is used. Replaced it with DevAsyncRead*    with the corrected number of parameters, 4 instead of 3. Renamed DevFillBack to*    DevWriteBack and corrected the number of parameters from 2 to 3. Both these calls*    currently do nothing and are not used by the printer drivers.*    * February 24, 1989    Suki Lee*    Added code to check if the slot is set to external before checking its protocol*    for Basic or Pascal device.*************************************************************************************************************************************                    Copyright 1986-1989*                    Apple Computer, Inc.*                    All Rights Reserved******************************************************************;------------------------------------------;; Equates from procedure ;;------------------------------------------VersionNb	equ $0200	; Version 2.0NoError	equ 0	; No errorPortNotOn	equ $1302	; Port not activeTrue	equ $FFFFFalse	equ $0000ch	equ $24	; For ApplePic card.ourch	equ $57BcardFlags	equ $0778col	equ $07F8;-----------------------------------------------;;   Imported addresses;;-----------------------------------------------	IMPORT alerttemp320	IMPORT alerttemp640;-----------------------------------------------;;   Forward addresses and entries;;-----------------------------------------------	ENTRY DevPrChanged	ENTRY DevStartup	ENTRY DevShutDown	ENTRY DevOpen	ENTRY DevRead	ENTRY DevWrite	ENTRY DevClose	ENTRY DevStatus	ENTRY DevAsyncRead	ENTRY DevWriteBack	ENTRY PrPortVer	ENTRY DevIsItSafe	ENTRY myTextWriteBlock	ENTRY CallCompletion	ENTRY Completion	ENTRY IsItSafe	ENTRY PortAlert	ENTRY Exit10	ENTRY Exit8	ENTRY Exit6	ENTRY Exit4	ENTRY Exit0	INCLUDE 'all.macros'; private macro definition	MACRO&lab	PushPtr &addr&lab	dc.B $F4	dc.W (&addr)>>16	dc.B $F4	dc.W &addr	MEND	EXPORT parallelCardparallelCard	PROC;-----------------------------------------------------------;; Header to denote new calls supported;	DC.W 0	; marker	DC.W (EndProcList-ProcList)/4 ; count of calls supported	jmp (ProcList,x)	rtl	ProcList	DC.L DevPrChanged	DC.L DevStartup	DC.L DevShutDown	DC.L DevOpen	DC.L DevRead	DC.L DevWrite	DC.L DevClose	DC.L DevStatus	DC.L DevAsyncRead	DC.L DevWriteBack	DC.L PrPortVer	DC.L DevIsItSafe	; new call added 16	apr 87EndProcList	EXPORT configedFlag	EXPORT configSlot	EXPORT sendAsIs	EXPORT whichSlot	EXPORT applePicCard	EXPORT initGraphics	EXPORT ApplePic	EXPORT graphiCardConfigDataconfigedFlag	DC.W 0	;Configured flag.configSlot	DC.W 0	;0 means scan.whichSlot	DC.W 0	;The slot DevStartup determined.applePicCard	DC.W 0sendAsIs	DC.W 1	;Some cards MAY not recognize any special chrs.initGraphics	DC.B 8	DC.B 9	DC.B 'N'	DC.B 9	DC.B 'K'	DC.B 09	;8-bits	DC.B 'H'	DC.B 09	;Transparent mode.	DC.B 'T'	DC.L 0,0ApplePIC	DC.W 0	DC.B 7	DC.B 9	DC.B '2'	DC.B '5'	DC.B '5'	DC.B 'N'	DC.B 9	DC.B 'K'graphiCard	DC.W 1	;Grappler cards work with this.	DC.B 8	DC.B 9	DC.B 'N'	DC.B 9	DC.B 'K'	DC.B 09	DC.B 'H'	DC.B 09	DC.B 'T'	ENDP*********************************************************************************************************************************************************************************************** DevPrChanged* * Called by Printer	driver when it has been changed.  Gives* us chance to tell	user there may be a	problem.* ***************************************************************	EXPORT DevPrChangedDevPrChanged	PROC	jsr IsItSafe	bcc Safe	pha	jsr PortAlert	; put up alert	plaSafe	jmp Exit4	ENDP***************************************************************** DevStartup**        LONG??? ** Seems to do nothing.* ***************************************************************	EXPORT DevStartupDevStartup	PROC	jsr IsItSafe	jmp Exit8	ENDP***************************************************************** DevShutDown** Does even less than startup since it takes no inputs.* ***************************************************************	EXPORT DevShutDownDevShutDown	PROC	jsr IsItSafe	jmp Exit0	ENDP***************************************************************** DevOpen**     OpenCompletion   LONG*     Reserved	   LONG* ***************************************************************	EXPORT DevOpenDevOpen	PROC	DefineStackDevOpen_DPage	word 0DevOpen_BReg	byte 0DevOpen_rtl1	block 3DevOpen_rtl2	block 3Reserved	long 0OpenCompletion	long 0	jsr IsItSafe	bcc OpenSafe	jmp Exit8OpenSafe	phd	phb	phk	plb	sta @slot	lda OpenCompletion,s	sta Completion	lda OpenCompletion+2,s	sta Completion+2	PushWord #0	PushLong @slot	_setOutputDevice	PushWord #$ffff	PushWord #0	_setoutGlobals	PushWord #1	_inittextDev	PushPtr InitGraphics+1	pushword #0	lda InitGraphics	and #$00ff	pha	_TextWriteBlock	lda applePicCard	beq @a	ldx whichSlot	lda >cardFlags,x	and #$FF7F	; Turn off vid-also.	sta >cardFlags,x@a	jsl CallCompletion	plb	pld	jmp Exit8@slot	DS.B 4	ENDP***************************************************************** DevRead**    Input*       PtrToBuffer	  LONG*       MaxToXfer	  WORD**    Output*       XferCount	  WORD****************************************************************	EXPORT DevReadDevRead	PROC	DefineStackDevRead_DPage	word 0DevRead_BReg	byte 0DevRead_rtl1	block 3DevRead_rtl2	block 3ReadRqd	word 0	10PtrReadBuf	long 0	12readTrnsfrd	word 0	16	jsr IsItSafe	bcc ReadSafe	jmp Exit6ReadSafe 	phd	phb	phk	plb	lda PtrReadBuf+2,s	;high word of buff addr	pha	lda PtrReadBuf+2,s	;low word	pha	lda PtrReadBuf+2,s	tax	lda #0	pha	;offset	phx	;size	pha	;echo flag	_TextReadBlock	plb	pld	jmp Exit6	ENDP***************************************************************** DevWrite**      WriteCompletion   LONG*      SrcBufPtr	     LONG*      Length	     WORD* ***************************************************************	EXPORT DevWriteDevWrite	PROC	DefineStackDevWrite_DPage	word 0DevWrite_BReg	byte 0DevWrite_rtl1	block 3DevWrite_rtl2	block 3WriteLengths	word 0WritePtrBuff	long 0WriteCompletion	long 0	jsr IsItSafe	bcc WriteSafe	jmp Exit10WriteSafe 	phd	phb	phk	plb	lda WriteCompletion,s	sta Completion	lda WriteCompletion+2,s	sta Completion+2	lda WritePtrBuff+2,s	pha	lda WritePtrBuff+2,s	pha	lda WriteLengths+4,s	tax	lda #0	pha	phx	jsr myTextWriteBlock	jsl CallCompletion	plb	pld	jmp Exit10	ENDP***************************************************************** DevClose** Yet another useful routine. * ***************************************************************	EXPORT DevCloseDevClose	PROC	jsr IsItSafe	jmp Exit0	ENDP***************************************************************** DevStatus** Another highly functional call.* ***************************************************************	EXPORT DevStatusDevStatus	PROC	jsr IsItSafe	jmp Exit4	ENDP***************************************************************** DevAsyncRead**   CompletionRoutine   LONG*   DataLength	    WORD*   PtrToBuffer	    LONG** output:*    actual length read WORD** Another really useful routine!* ***************************************************************	EXPORT DevAsyncReadDevAsyncRead	PROC	DefineStackAsyncRead_DPage	word 0AsyncRead_BReg	byte 0AsyncRead_rtl1	block 3AsyncRead_rtl2	block 3ReadBuffer	long 0ReadLength	word 0ReadComplete	long 0ActualLength	word 0	jsr IsItSafe	bcc Yes 	jmp Exit10Yes		lda #0	sta actualLength,s			   	jmp Exit10	ENDP****************************************************************	THIS FUNCTION NOT SUPPORTED YET !!!** DevWriteBack* *      Completion routine ptr   LONG*      BufferSize	            WORD*      BufferAddress            LONG****************************************************************	EXPORT DevWriteBackDevWriteBack	PROC	DefineStack		jsr IsItSafe	jmp Exit10 	ENDP************************************* PrPortVer ** Returns version #	of currently installed port*************************************************************	EXPORT PrPortVerPrPortVer	PROC	DefineStackRtl1	Block 3Rtl2	Block 3Version	Word 0	lda #VersionNb	sta Version,s	lda #0	jmp Exit0	ENDP***************************************************************** DevIsItSafe**    Output:  Safety    WORD    boolean** * EntryPoint to driver from outside.** Safety is true if	it is safe, false if not.* ***************************************************************	EXPORT DevIsItSafeDevIsItSafe	PROC	DefineStackRTL1	block 3RTL2	block 3Result	word	jsr IsItSafe	bcc Yes	lda #False	sta Result,sGetOut	lda #0	jmp Exit0Yes	lda #True	sta Result,s	bra GetOut	ENDP************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************************	EXPORT myTextWriteBlockmyTextWriteBlock	PROCstrLen	equ 1strOffset	equ strLen+2textPtr	equ strOffset+2	pla	;Handle stack frame rather oddly.	sta @keepRts	tdc	sta @keepDirReg	tsc	tcd	lda sendAsIs	bne @dumpRest	lda #$89	sta @currentEsc@dumpHunk	ldy strOffset	ldx #0@dh0	cpx strlen	beq @dumpRest	cpx #16	;There is a limit in the firmware -- 	bcs @dumpAndSwitch	;  don't know why.	lda [textPtr],y	eor @currentEsc	and #$007F	;Detect $09 or $89.	beq @dumpAndSwitch	inx	iny	bra @dh0@dumpAndSwitch	ldy #4@cloneStkFrame	lda 7,s	pha	dey	bne @cloneStkFrame	txa	sta strLen,s	;Length for this segment.	clc	adc strOffset	sta strOffset	;Next segment will start here.	lda strLen	sec	sbc strLen,s	sta strLen	;# of characters remaining for next pass.	lda #0	;Don't let card think that we are	sta >ch	;  printing a long line.	ldx whichSlot	sta >col,x	_TextWriteBlock	;Dump...	lda @currentEsc	pha	_WriteChar	lda @currentEsc	eor #8	sta @currentEsc	pha	_WriteChar	bra @dumpHunk@dumpRest	_TextWriteBlock	tay	;Keep error code.	lda sendAsIs	bne @exit	lda @currentEsc	cmp #$89	beq @exit	pha	_WriteChar	pea #$89	_WriteChar@exit	lda @keepDirReg	tcd	ldx @keepRts	phx	tya	;Error code.	rts@keepRts	DC.W 0@keepDirReg	DC.W 0@currentEsc	DC.W 0	ENDP	EXPORT CallCompletionCallCompletion	PROC       	lda Completion	ora Completion+2	bne doit	RtlDoit 	lda Completion+1	pha	phb	pla	lda Completion	sec	sbc #1	pha	rtl	EXPORT CompletionCompletion       	DS.B 4	ENDP***************************************************************** IsItSafe** Common routine to	see if the device we want to deal with* is switched in.** If it is safe, a-reg is xet to zero and carry is clear.* If it is NOT safe, a-reg is set to error code and carry is*    set. * ***************************************************************	EXPORT IsItSafeIsItSafe	PROC	phb	;Save data bank reg.	phk	plb	stz whichSlot	;To be determined.	stz applePicCard	;Special stuff for our card.	lda #$0002	; set the mask for slot 1 to start	sta slotNumMask	* It seems that DevStartup should determine what slot, etc.,* but it is currently not the first function to be called.* DevIsItSafe is the first function.  If this is to change,* then this function is the only safe place to put this* initialization code, even though it will get done much* more than necessary.	ldx configSlot	bne SLoop	;User says it is here.	inx	;Do a scan for it.SLoop	lda >$E0C02D	; slot state soft switch	and slotNumMask	; check appropriate bit	beq Internal	; bit cleared means internal, so move on			; We're here, slot must be set to "Your Card"	lda #0	;Shift slot # to high byte.	txa	xba	tax	sep #%00100000	; no full native mode	longa off	lda >$E0C005,x	cmp #$48	;Basic device I.D.	bne tryPascal	cmp >$E0C007,x	bne NotSlot	inc applePicCard	ldy #(ApplePic-ApplePic)IsSlot	phx	ldx #0@s0	lda ApplePic,y	sta sendAsIs,x	iny	inx	cpx #11	bcc @s0	rep #%00100000	;Back to full native mode.	longa on	pla	xba	;Put slot in acc	tax	sta whichSlot	clc	plb	rts	;It is safe.	longa off	;Branched to not in full native.tryPascal	cmp #$38	bne NotSlot	lda >$E0C007,x	cmp #$18	bne NotSlot	ldy #(graphiCard-ApplePIC)	lda >$E0C00B,x	cmp #1	beq IsSlot	;This is a pascal device.NotSlot	rep #%00100000	;Back to full native mode.	longa on	txa	xba	ldx configSlot	bne NotSafe	;User said which slot to try.	taxInternal	asl slotNumMask	; adjust the mask for the next slot	inx	cpx #8	bcc SLoopNotSafe	sec	plb	rtsslotNumMask	DS.B 2	; mask for the slot soft switch	ENDP****************************************************************** PortAlert** Alert box to tell	user that the appropriate port is not turned* on.** no parameters on stack*****************************************************************	EXPORT PortAlertPortAlert	PROC		;using DialogData	_InitCursor	; restore cursor back to arrow	pha	; make room for result	_GetMasterSCB	pla	pha	; make room for result of alert call 	and #$80	; check mode 	beq mode320	; 320 mode	pushlong #alerttemp640 ; use 640 mode template	bra GoOnmode320	pushlong #alerttemp320 ; use 320 mode templateGoOn	pushlong #$0000	_StopAlert;              jsr WaitCursor	; set to watch again	pla	; get the item hit off stack	rts	ENDPexitRoutines	PROC	EXPORT Exit10Exit10       	tax	lda 5,s	sta 15,s	lda 3,s	sta 13,s	lda 1,s	sta 11,s	tsc	clc	adc #10	tcs	bra exitZZ	EXPORT Exit8Exit8       	tax	Standart 8 bytes input exit	lda 5,s	sta 13,s	lda 3,s	sta 11,s	lda 1,s	sta 9,s	pla	pla	pla	pla	bra exitZZ	EXPORT Exit6Exit6       	tax	Standart 6 bytes input exit	lda 5,s	sta 11,s	lda 3,s	sta 9,s	lda 1,s	sta 7,s	pla	pla	pla	bra exitZZ	EXPORT Exit4Exit4       	tax	Standart 4 bytes input exit	lda 5,s	sta 9,s	lda 3,s	sta 7,s	lda 1,s	sta 5,s	pla	plaexitZZ	txa	EXPORT Exit0Exit0       	cmp #1	Standart 0 byte input exit	rtl	ENDP	END